721:     /// <summary>
722:     /// P0优化：预热线程池 - 消除首次Task.Run的冷启动延迟
723:     /// 预期效果：首张缩略图加载从1783ms降至~50ms
724:     /// </summary>
725:     private void PrewarmThreadPool()
726:     {
727:         try
728:         {
729:             // 设置最小线程数，确保线程池立即可用
730:             ThreadPool.GetMinThreads(out int minWorker, out int minIO);
731:             ThreadPool.SetMinThreads(
732:                 Math.Max(minWorker, 8),  // 至少8个工作线程
733:                 Math.Max(minIO, 4)       // 至少4个IO线程
734:             );
735: 
736:             // 预热：启动几个空任务，强制线程池创建线程
737:             var warmupTasks = new Task[4];
738:             for (int i = 0; i < 4; i++)
739:             {
740:                 warmupTasks[i] = Task.Run(() => Thread.Sleep(10));
741:             }
742:             Task.WaitAll(warmupTasks);
743:         }
744:         catch (Exception ex)
745:         {
746:             VisionLogger.Instance.Log(LogLevel.Warning, $"线程池预热失败: {ex.Message}", "App");
747:         }
748:     }
