259:     /// <summary>
260:     /// LRU图像缓存（全分辨率图像，上限 30）
261:     /// </summary>
262:     public class ImageCache
263:     {
264:         private readonly int _maxCacheSize;
265:         private readonly Dictionary<string, LinkedListNode<CacheEntry>> _cacheMap;
266:         private readonly LinkedList<CacheEntry> _lruList;
267: 
268:         public ImageCache(int maxCacheSize = 30)
269:         {
270:             _maxCacheSize = maxCacheSize;
271:             _cacheMap = new Dictionary<string, LinkedListNode<CacheEntry>>();
272:             _lruList = new LinkedList<CacheEntry>();
273:         }
274: 
275:         /// <summary>
276:         /// 查询缓存（命中则提升 LRU 优先级）。调用方须在外部加锁（仅保护字典，短临界区）。
277:         /// </summary>
278:         public BitmapSource? Get(string filePath)
279:         {
280:             lock (_cacheMap)
281:             {
282:             if (_cacheMap.TryGetValue(filePath, out var node))
283:             {
284:                 _lruList.Remove(node);
285:                 _lruList.AddFirst(node);
286:                 return node.Value.Bitmap;
287:             }
288:             return null;
289:             }
290:         }
291: 
292:         /// <summary>
293:         /// 写入缓存（含 LRU 淘汰）。调用方须在外部加锁。已在缓存中则不重复写入。
294:         /// </summary>
295:         public void Set(string filePath, BitmapSource? bitmap)
296:         {
297:             lock (_cacheMap)
298:             {
299:             if (bitmap == null || _cacheMap.ContainsKey(filePath)) return;
300: 
301:             var entry = new CacheEntry(filePath, bitmap);
302:             var newNode = _lruList.AddFirst(entry);
303:             _cacheMap[filePath] = newNode;
304: 
305:             if (_lruList.Count > _maxCacheSize)
306:             {
307:                 var lastNode = _lruList.Last;
308:                 if (lastNode != null)
309:                 {
310:                     _cacheMap.Remove(lastNode.Value.FilePath);
311:                     _lruList.RemoveLast();
312:                 }
313:             }
314:             }
315:         }
316: 
317:         public void Remove(string path)
318:         {
319:             lock (_cacheMap)
320:                 if (_cacheMap.Remove(path, out var node)) _lruList.Remove(node);
321:         }
322: 
323:         public void Clear()
324:         {
325:             lock (_cacheMap)
326:             {
327:                 _cacheMap.Clear();
328:                 _lruList.Clear();
329:             }
330:         }
