538:         /// <summary>
539:         /// WIC 缩略图解码核心（无锁，可在后台线程并行执行）
540:         /// </summary>
541:         private static BitmapImage DecodeThumbnailCore(string filePath)
542:         {
543:             var bitmap = new BitmapImage();
544:             bitmap.BeginInit();
545:             bitmap.UriSource = new Uri(filePath, UriKind.RelativeOrAbsolute);
546:             bitmap.DecodePixelWidth = 100;                // 解码时直接缩小，省内存
547:             bitmap.CacheOption = BitmapCacheOption.OnLoad; // 立即解码
548:             bitmap.EndInit();
549:             bitmap.Freeze();                              // 冻结后可跨线程
550:             return bitmap;
551:         }
